EPISODE = {'id': '08', 'sid': 'course', 'series': '云计算保姆级教程 · 从零到实战', 'title': 'Windows Server 基础（另一半世界）', 'slides': [{'type': 'cover', 'title': '第 8 章 · Windows Server 基础（另一半世界）', 'subtitle': '保姆级视频课 · 第 08 集', 'items': ['云是混合的：Linux 管一半，Windows 管另一半。', '企业的"域环境"（AD）几乎全是 Windows。'], 'narration': '欢迎来到云计算保姆级教程视频课。云是混合的：Linux 管一半，Windows 管另一半。企业的"域环境"（AD）几乎全是 Windows。'}, {'type': 'steps', 'title': '本章路线图：我们会走过这些站', 'accent': (56, 189, 248), 'steps': [{'t': '先搞清楚：Windows Se', 'd': ''}, {'t': '准备实验环境', 'd': ''}, {'t': '核心实战 1：搭建域控制器（A', 'd': ''}, {'t': '核心实战 2：Windows ', 'd': ''}, {'t': '核心实战 3：文件共享与 DF', 'd': ''}, {'t': '核心实战 4：组策略（GPO）', 'd': ''}], 'narration': '先看这条路线。这一章一共 9 个部分，我们先重点走这几站：先搞清楚：Windows Ser、准备实验环境、核心实战 1：搭建域控制器（AD、核心实战 2：Windows 上、核心实战 3：文件共享与 DFS、核心实战 4：组策略（GPO）—。跟着顺序来，每一站我都会告诉你要点在哪里。'}, {'type': 'bullets', 'title': '先搞清楚：Windows Server 到底是什么……', 'items': [{'t': '它和 Windows 10/11 的区别', 'd': '界面长得差不多，但用途完全不同：Server 版专门给企业"当服务器"用'}, {'t': '什么是"域"（AD）？为什么企业离不开它', 'd': '你有 500 名员工的电脑要管理：每个人有自己的账号密码、每台电脑的权限策略、共享文件夹谁能……'}], 'accent': (56, 189, 248), 'narration': '先搞清楚：Windows Server 到底是什么……。比喻：域 = 公司的大人事系统+大门口禁系统。域控制器 = 人事部。员工账号 = 工牌。组策略 = 公司规章制度（自动下发到每台电脑）。 世界赛 Module B 的比赛环境：一堆 Windows Server VM（DC1、DC2、文件服务器、Web 服务器、路由器…），要求你从零搭出一整套域环境并配置各种策略。本章就是那个比赛的入门训练。'}, {'type': 'bullets', 'title': '准备实验环境', 'items': [{'t': '下载与安装', 'd': '搜索 "Windows Server 2022 评估版"'}, {'t': '装完后先做三件事', 'd': '改计算机名（域环境里名字很重要）'}, {'t': '认识 PowerShell（Windows 的命令行）', 'd': '开始菜单搜索 PowerShell（蓝色图标），右键"以管理员身份运行"。'}], 'accent': (251, 191, 36), 'narration': '准备实验环境。PowerShell 的心法：动词-名词（Verb-Noun）。Get- 是拿、Set- 是设、New- 是新建、Remove- 是删。看懂模式，命令不用背。 实战几个：\n``powershell\nGet-ComputerInfo | Select-Object CsName, WindowsVersion   # 看系统信息\nGet-Service | Where-Object {$.Status -eq "Running"} | Select-Object -First 10   # 运行中的服务\nipconfig /all                                              # 看网络配置（老命令依然好使）\n`\n管道 |` 在 PowerShell 里更强大（对象级处理），和 Linux 一个思路。'}, {'type': 'bullets', 'title': '核心实战 1：搭建域控制器（AD DS）', 'items': [{'t': '安装 AD DS 角色', 'd': '图形方式（学习期先用图形，熟了再上 PowerShell）'}, {'t': '提升为域控', 'd': '选择 "添加新林"（全新域名）'}, {'t': '建组织架构（OU / 用户 / 组）——Module B 评分点同款', 'd': '先建 OU（组织单位 = 文件夹式的部门结构）'}, {'t': '加域：让另一台机器"入伙"', 'd': '在另一台 Windows Server（比如 FILE-SRV）上'}], 'accent': (52, 211, 153), 'narration': '核心实战 1：搭建域控制器（AD DS）。重启后用域管理员登录：用户名 MYCOMPANY\\Administrator（或 Administrator@mycompany.local） 验证：\n``powershell\nGet-ADDomain                 # 显示域信息（默认需要 RSAT 工具，域控上自带）\nGet-ADDomainController       # 看域控状态\n``\n或在"管理工具"里打开 Active Directory 用户和计算机——这就是"人事部管理系统"的界面。'}, {'type': 'bullets', 'title': '核心实战 2：Windows 上的 DNS 服务器', 'items': [{'t': '管理工具 → DNS', 'd': ''}, {'t': '展开', 'd': '正向查找区域 → mycompany.local ——能看到域控自动生成的记录（域控自己、msdcs 等）'}, {'t': '手动建记录（右键区域 → 新建主机 A 记录）：', 'd': ''}, {'t': 'www → 192.168.10.20', 'd': ''}, {'t': 'mail → 192.168.10.21', 'd': ''}], 'accent': (167, 139, 250), 'narration': '核心实战 2：Windows 上的 DNS 服务器。域控装 AD 时已经自带 DNS。验证与操作（Module B 的 NW-SRV 考点是"从区传输"）：\n1. 管理工具 → DNS\n2. 展开：正向查找区域 → mycompany.local ——能看到域控自动生成的记录（域控自己、msdcs 等）\n3. 手动建记录（右键区域 → 新建主机 A 记录）：\n   - www → 192.168.10.20\n   - mail → 192.168.10.21\n4. 反向查找区域：右键"反向查找区域" → 新建 → 网络 ID 填 192.168.10 → 完成\n5. 验证：nslookup www.mycompany.local 192.168.10.10 辅助区域（从区传输）实验（评分点技能）：\n- 在第二台服务器（装 DNS 角色）上：右键 → 新建区域 → 辅助区域 → 名称 mycompany.local → 主服务器填 192.168.10.10\n- 成功同步后能看到和主一样的记录。'}, {'type': 'bullets', 'title': '核心实战 3：文件共享与 DFS', 'items': [{'t': '基础共享（FILE-SRV 上）', 'd': '```powershell'}, {'t': '权限的"双门规则"（超重要，Module B 重灾区）', 'd': 'Windows 文件访问要过两道门'}, {'t': 'DFS（分布式文件系统）', 'd': '一块共享不够用？DFS 把多个共享"拼"成一棵逻辑树，比如 \\\\paris.local\\CS……'}], 'accent': (248, 113, 113), 'narration': '核心实战 3：文件共享与 DFS。DFS 复制：两个服务器上的文件夹互相同步（改一边，另一边自动更新）——Module B 有"File Replication"评分点。。基础共享（FILE-SRV 上），```powershell；权限的"双门规则"（超重要，Module B 重灾区），Windows 文件访问要过两道门；DFS（分布式文件系统），一块共享不够用？DFS 把多个共享"拼"成一棵逻辑树，比如 \\\\paris.local\\CS……'}, {'type': 'bullets', 'title': '核心实战 4：组策略（GPO）——Module B ……', 'items': [{'t': '六个"世赛同款"策略实战（对照 Module B 评分点）', 'd': '① 登录消息横幅（用户登录时显示警告文字）'}, {'t': '验证与排错（比赛检查也这么看）', 'd': '```powershell'}], 'accent': (56, 189, 248), 'narration': '核心实战 4：组策略（GPO）——Module B ……。组策略 = 批量下发的"规章制度"。你在域控上写一条策略，全公司电脑/用户生效。 ① 登录消息横幅（用户登录时显示警告文字）\n路径：计算机配置 → 策略 → Windows 设置 → 安全设置 → 本地策略 → 安全选项\n→ "交互式登录：试图登录的用户的消息标题" + "消息文本" ② 禁用本地 Administrator 账户\n同路径 → "账户：管理员账户状态" → 已禁用 ③ 禁止存储 LM 哈希（安全加固）\n同路径 → "网络安全：不要在下次更改密码时存储 LAN Manager 的哈希值" → 已启用 ④ 统一环境变量（评分点里那个奇怪的 TheErasTour=2024 就是这种题）\n用户配置 → 首选项 → Windows 设置 → 环境 → 新建 ⑤ 禁用注册表编辑器 & 命令提示符（限制普通用户乱搞）\n用户配置 → 管理模板 → 系统 → "阻止访问注册表编辑工具"、"阻止访问命令提示符"——注意：只对某几个部门限制？'}, {'type': 'bullets', 'title': '核心实战 5：IIS 网站 + 证书', 'items': [{'t': 'IIS 管理器 → 右键"网站" → 添加网站：', 'd': ''}, {'t': '名称', 'd': 'mycompany'}, {'t': '物理路径', 'd': 'C:\\inetpub\\mycompany（先建好文件夹放个 index.html）'}, {'t': '绑定', 'd': 'http，主机名 www.mycompany.local，端口 80'}, {'t': '本地 hosts 或 DNS 把 www.mycompany.local 指到这台机器', 'd': ''}], 'accent': (251, 191, 36), 'narration': '核心实战 5：IIS 网站 + 证书。建一个新站点（Module B 的 WEB-SRV 是在 IIS 上建虚拟主机 + HTTPS 无错误）：\n1. IIS 管理器 → 右键"网站" → 添加网站：\n   - 名称：mycompany\n   - 物理路径：C:\\inetpub\\mycompany（先建好文件夹放个 index.html）\n   - 绑定：http，主机名 www.mycompany.local，端口 80\n2. 本地 hosts 或 DNS 把 www.mycompany.local 指到这台机器\n3. 浏览器访问 http://www.mycompany.local → 出现你的页面 配 HTTPS（AD CS 签发 + IIS 绑定）：\n1. 域控上装 AD CS（服务器管理器 → 添加角色 → Active Directory 证书服务 → 勾选"证书颁发机构"）\n2. Web 服务器上：IIS → 服务器证书 → 创建域证书 → 填信息 → 颁发机构选 myc……'}, {'type': 'note', 'text': '把上面的操作脚本化——Module B 评分点"用自动脚本创建用户"就是这个：\n``powershell\n# 例子：一键检查本机是否满足域成员条件\n$dns = (Get-DnsClientS……', 'sub': '', 'accent': (52, 211, 153), 'narration': 'PowerShell 自动化速成（加分项）。把上面的操作脚本化——Module B 评分点"用自动脚本创建用户"就是这个：\n``powershell\n# 例子：一键检查本机是否满足域成员条件\n$dns = (Get-DnsClientServerAddress -AddressFamily IPv4 | Where-Object {$.ServerAddresses}).ServerAddresses\nWrite-Host "DNS 服务器: $dns"\nif ($dns -contains "192.168.10.10") { Write-Host "DNS 正确 ✓" -ForegroundColor Green }\nelse { Write-Host "DNS 指向错误！加域会失败" -ForegroundColor Red }\n``\n建议：把本章所有图形操作，自己用 PowerShell 再实现一遍。这就是从"会用"到"熟练"的分水岭。'}, {'type': 'note', 'text': '练习（能全做出来，Module B 你就入门了），装一台 Windows Server，改名为 DC1，建域 mycompany.local', 'sub': '', 'accent': (167, 139, 250), 'narration': '练习与自我检验。练习（能全做出来，Module B 你就入门了），装一台 Windows Server，改名为 DC1，建域 mycompany.local'}, {'type': 'end', 'kicker': '第 08 集 · 完', 'title': '下一集\n第 09 集 · Shell 脚本进阶', 'sub': '配套图文：打开教程对应章节，边看视频边动手', 'next': '练完记得去训练场实战（wsarena）· 不懂就回看本集', 'narration': '第 08 集到这里就结束了。下一集我们学习Shell 脚本进阶。记住：视频看一遍，图文过一遍，动手练一遍，三遍下来才算真的学会。我们下一集见！'}]}
